use crate::aap::caps::inference_llm::infer;

struct Node;

/// Map a free-text label from the model onto the closed `Intent` set. The enum
/// has no "other" case, so adversarial text cannot widen the intent set; anything
/// unrecognised collapses to `Unknown`, satisfying the `ensures` by construction.
fn classify_intent(label: &str) -> Intent {
    let l = label.trim().to_ascii_lowercase();
    // Take the first token so stray punctuation/explanation doesn't defeat the match.
    let tok = l
        .split(|c: char| !(c.is_ascii_alphanumeric() || c == '_' || c == '-'))
        .find(|s| !s.is_empty())
        .unwrap_or("");
    match tok {
        "billing_question" | "billing" | "billing-question" => Intent::BillingQuestion,
        "technical_support" | "technical" | "technical-support" | "support" => {
            Intent::TechnicalSupport
        }
        "account_change" | "account" | "account-change" => Intent::AccountChange,
        "general_inquiry" | "general" | "general-inquiry" | "inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

/// Enforce `len(question) <= 512` at a UTF-8 char boundary, counting characters
/// (the Python-side `len` of a `str`). This is the node's own guarantee on its
/// output, independent of whether the model respected the instruction.
fn bound_question(s: &str) -> String {
    const MAX: usize = 512;
    if s.chars().count() <= MAX {
        s.to_string()
    } else {
        s.chars().take(MAX).collect()
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // `task` is the one-word routing hint named for this kind of request.
        let system = "You classify one customer support message. \
Reply with exactly two lines. \
Line 1: the intent, one of billing_question, technical_support, account_change, general_inquiry, unknown. \
Line 2: a single concise question (<=512 chars) restating what the customer wants. \
Output nothing else.";

        let raw = infer(system, &message.text, "classify");

        let mut lines = raw.lines();
        let intent_line = lines.next().unwrap_or("");
        let question_line = lines.next().unwrap_or("").trim();

        let intent = classify_intent(intent_line);

        // Prefer the model's restated question, but never emit empty; fall back
        // to the (bounded) original text. Either way the length ensure holds.
        let question_src = if question_line.is_empty() {
            message.text.trim()
        } else {
            question_line
        };
        let question = bound_question(question_src);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

